import numpy as np
from scipy.spatial.transform import Rotation, Slerp
import vlb_tool

class Controller:
    def __init__(self, session):
        self.s = session

    def move(self, p, quat=(0, 1, 0, 0), grip=.04, n=None, settle=5):
        s = self.s
        p = np.array(p, float)
        p0 = s.env.get_ee_pos().copy()
        q0 = s.env.get_ee_quat().copy()
        interp = Slerp([0, 1], Rotation.from_quat(np.array([q0, quat])[:, [1, 2, 3, 0]]))
        if n is None:
            n = max(10, int(np.linalg.norm(p-p0)/.006))
        for t in np.linspace(0, 1, n+1)[1:]:
            if s.done:
                return
            qt = interp(t).as_quat()[[3, 0, 1, 2]]
            ik = s.ik(p0+(p-p0)*t, qt)
            s.step(np.r_[ik['joint_positions'], grip, grip])
        for _ in range(settle):
            if not s.done:
                s.step(s.targets)

    def hold(self, grip, n=10):
        for _ in range(n):
            if not self.s.done:
                self.s.step(np.r_[self.s.targets[:7], grip, grip])


